export function MascotPlan({ className }: { className?: string }) {
  const id = useId();
  const patternId = "pattern0_" + id;
  const imageId = "image0_" + id;

  return (
 <svg className={className} width="147" height="204" viewBox="0 0 147 204" fill="none" xmlns="http://www.w3.org/2000/svg" >
<rect width="147" height="204" fill={`url(#${patternId})`}/>
<defs>
<pattern id={patternId} patternContentUnits="objectBoundingBox" width="1" height="1">
<use href={`#${imageId}`} xlinkHref={`#${imageId}`} transform="matrix(0.00524922 0 0 0.00378522 -0.926897 -0.481209)"/>
</pattern>
<image id={imageId} width="558" height="447" preserveAspectRatio="none" href={mascotPlanUrl}/>
</defs>
</svg>


  );
}

